// Запуск и завершение настоящего мониторинга (создаёт сеанс в «היסטוריה» — тесты с пометкой @data).
// Такие тесты идут только с BANCI_MONITORING=1 (правило README: по умолчанию мониторинг не запускается).
import { by, assert, skip, checkedFromValue } from './appium.mjs';
import { passSafetyCheck } from './banci.mjs';

/** Тест запускает мониторинг — только по явному разрешению BANCI_MONITORING=1. */
export function requireMonitoringOptIn() {
  if (process.env.BANCI_MONITORING !== '1') {
    skip('тест запускает мониторинг (сеанс в «היסטוריה») — запуск только с BANCI_MONITORING=1; телефон на зарядке, камера смотрит на освещённую сцену');
  }
}

/** Таймер вверху экрана мониторинга «H:MM:SS» → секунды. Время событий в ленте того же формата — берём самый верхний. */
const TIMER = 'label MATCHES "^[0-9]+:[0-9]{2}:[0-9]{2}$" AND type == "XCUIElementTypeStaticText"';
export async function timerSeconds(app) {
  const els = await app.findAll(TIMER);
  assert(els.length, 'таймер мониторинга «H:MM:SS» виден');
  let best, bestY = Infinity;
  for (const e of els) {
    const r = await e.rect();
    if (r.y < bestY) { bestY = r.y; best = e; }
  }
  const [h, m, s] = String(await best.attr('label')).split(':').map(Number);
  return h * 3600 + m * 60 + s;
}

/** Ждёт, пока таймер дойдёт до sec секунд (опрос результата). */
export async function waitTimer(app, sec, { timeout = sec * 1000 + 30000 } = {}) {
  const end = Date.now() + timeout;
  let t = -1;
  while (Date.now() < end) {
    t = await timerSeconds(app);
    if (t >= sec) return t;
    await new Promise((r) => setTimeout(r, 1000));
  }
  throw new Error(`Проверка не прошла: таймер мониторинга не дошёл до ${sec} с (сейчас ${t} с)`);
}

/** «בית» → «התחלת ניטור» → проверка → камера → «מי בבריכה היום?» → «התחלת ניטור» → экран мониторинга со статусом «תקין». */
export async function startMonitoring(app) {
  await passSafetyCheck(app);

  // Шаг 2 «כיוון מצלמה»: отметить «כל שטח המים נראה…», если не отмечен.
  const water = await app.waitFor(by.begins('כל שטח המים נראה'), { timeout: 20000, what: 'чекбокс «כל שטח המים נראה…» на шаге камеры' });
  if (checkedFromValue(await water.attr('value')) !== true) await water.click();
  const next = await app.waitFor(by.exact('המשך', 'Button'), { what: '«המשך» на шаге камеры' });
  const end = Date.now() + 20000;
  while (!(await next.enabled())) {
    if (Date.now() > end) throw new Error('ПРЕДУСЛОВИЕ: «המשך» на шаге камеры неактивна (тёмный/чёрный кадр, подсказка «כוונו…») — направить камеру на освещённую сцену');
    await new Promise((r) => setTimeout(r, 300));
  }
  await next.click();

  // Шаг 3 «מי בבריכה היום?» → «התחלת ניטור». Если кнопка серая — выбрать первого ребёнка.
  await app.waitFor(by.contains('מי בבריכה היום'), { timeout: 15000, what: 'шаг 3 «מי בבריכה היום?»' });
  const start = await app.waitFor(by.exact('התחלת ניטור', 'Button'), { what: '«התחלת ניטור» на шаге 3' });
  if (!(await start.enabled())) {
    const boxes = await app.findAll('value BEGINSWITH[c] "checkbox" OR value CONTAINS "מסומן"');
    for (const b of boxes) {
      if (!/בחירת כולם|כל שטח המים/.test(String(await b.attr('name') ?? ''))) { await b.click(); break; }
    }
  }
  await start.click();

  // Экран мониторинга: «היסטוריית אירועים», статус «תקין», таймер.
  await app.waitFor(by.contains('היסטוריית אירועים'), { timeout: 30000, what: 'экран мониторинга («היסטוריית אירועים»)' });
  await app.waitFor(by.exact('תקין'), { timeout: 30000, what: 'статус «תקין» на превью' });
  await timerSeconds(app);
}

/** Завершить мониторинг слайдером «כבה את המצלמה» (ручка справа, тянуть влево до конца) → итог «מה קרה». */
export async function endMonitoring(app) {
  const label = await app.waitFor(by.contains('כבה את המצלמה'), { what: 'слайдер «כבה את המצלמה»' });
  const r = await label.rect();
  const { width } = await app.windowRect();
  const y = r.y + r.height / 2;
  await app.exec('mobile: dragFromToForDuration', { duration: 0.5, fromX: Math.round(width * 0.86), fromY: Math.round(y), toX: Math.round(width * 0.08), toY: Math.round(y) });
  await app.waitFor(by.contains('מה קרה'), { timeout: 20000, what: 'итог мониторинга («מה קרה») после «כבה את המצלמה»' });
}

// ---- #8d2595: сбой «המכשיר זז» (окно 10.2) и ложные тревоги опасности ----
export const MOVED = 'המכשיר זז';
export const MOVED_TEXTS = ['הבריכה לא במעקב — השגיחו עליה בעצמכם.', 'הטלפון זז מהמקום. כדי לחזור לניטור:'];
export const MOVED_BUTTONS = ['כיוון מחדש', 'סיום ניטור'];
export const DANGER = 'זוהתה סכנה בבריכה';
const ts = () => new Date().toTimeString().slice(0, 8);

/** Окно/событие «המכשיר זז» на экране (окно сбоя или строка в «היסטוריית אירועים»). */
export const movedVisible = (app) => app.exists(by.contains(MOVED));

/**
 * Ложная тревога опасности (#18bb68 — отдельный реджект): НЕ провал теста #8d2595, только лог + скриншот.
 * Возвращает true, пока окно тревоги на экране. log — массив, куда пишется время тревоги.
 */
export async function logDangerAlarm(app, log, tag) {
  if (!(await app.exists(by.contains(DANGER)))) return false;
  if (!log.open) {
    log.open = true;
    const shot = await app.screenshot(`${tag}-danger-${ts().replace(/:/g, '')}`).catch(() => undefined);
    log.push({ at: ts(), shot });
    console.log(`     [#18bb68, не провал] ${ts()} ложная тревога «${DANGER}» → ${shot ?? 'без скриншота'}`);
  }
  return true;
}
export function dangerClosed(log) { log.open = false; }

/** Если на экране осталась ложная тревога — закрыть «זו אזעקת שווא» (не «חיוג ל-101»!), чтобы дойти до слайдера. */
export async function dismissFalseDanger(app) {
  if (!(await app.exists(by.contains(DANGER)))) return false;
  await app.tap(by.exact('זו אזעקת שווא', 'Button'), { timeout: 5000, what: '«זו אזעקת שווא» в окне ложной тревоги' });
  await app.waitGone(by.contains(DANGER), { timeout: 10000, what: `окно «${DANGER}»` });
  console.log(`     [#18bb68] ${ts()} ложная тревога закрыта «זו אזעקת שווא»`);
  return true;
}

// ---- #7b5462: «היסטוריית אירועים» без повторов «המצלמה הפסיקה לפעול» / «הניטור חזר לפעול» ----
export const EV = {
  START: 'התחלת ניטור',
  BACKGROUND: 'האפליקציה ירדה לרקע',
  HIDDEN: 'משהו הסתיר את האפליקציה',
  DISCONNECTED: 'החיבור נותק',
  CAMERA_STOPPED: 'המצלמה הפסיקה לפעול',
  RESUMED: 'הניטור חזר לפעול',
};
/** События сбоя: на каждое должно прийти ровно одно «הניטור חזר לפעול». */
export const FAILURE_EVENTS = [EV.BACKGROUND, EV.HIDDEN, EV.DISCONNECTED, EV.CAMERA_STOPPED];
const TIME_RE = /^([0-9]+):([0-9]{2}):([0-9]{2})$/;
const toSec = (label) => { const m = TIME_RE.exec(String(label)); return m ? +m[1] * 3600 + +m[2] * 60 + +m[3] : null; };

/** Строки «היסטוריית אירועים», видимые сейчас: [{ title, t (сек мониторинга), time }]. Время — ближайший «H:MM:SS» под заголовком в той же карточке. */
async function visibleEvents(app, titles) {
  const times = [];
  for (const e of await app.findAll(TIMER)) {
    const label = await e.attr('label');
    times.push({ label, t: toSec(label), r: await e.rect() });
  }
  const out = [];
  for (const title of titles) {
    for (const e of await app.findAll(by.exact(title, 'StaticText'))) {
      const r = await e.rect();
      const below = times.filter((x) => x.r.y > r.y && x.r.y - r.y < 90).sort((a, b) => a.r.y - b.r.y)[0];
      if (below) out.push({ title, t: below.t, time: below.label });
    }
  }
  return out;
}

/**
 * Все события «היסטוריית אירועים» (с прокруткой списка до конца и обратно наверх), без дублей (заголовок + время).
 * Новые события сверху; возвращает отсортированными по времени мониторинга.
 */
export async function collectEvents(app, titles = Object.values(EV)) {
  const seen = new Map();
  let idle = 0;
  for (let i = 0; i < 10 && idle < 2; i++) {
    const before = seen.size;
    for (const ev of await visibleEvents(app, titles)) seen.set(`${ev.title}|${ev.time}`, ev);
    idle = seen.size === before && i > 0 ? idle + 1 : 0;
    await app.exec('mobile: swipe', { direction: 'up' }); // прокрутка списка вниз
  }
  for (let i = 0; i < 6 && !(await app.exists(by.exact('תקין'))); i++) {
    await app.exec('mobile: swipe', { direction: 'down' }); // обратно наверх, до превью со статусом
  }
  return [...seen.values()].sort((a, b) => a.t - b.t);
}

export const countOf = (events, title, fromSec = 0) => events.filter((e) => e.title === title && e.t >= fromSec).length;
export const fmtEvents = (events) => events.map((e) => `${e.time} ${e.title}`).join(' · ');
